const siteNames = Object.keys(bookSites);
const currentUrl = getCurrentUrl();
const currentSiteName = getNameByUrl(String(currentUrl));

const mainUI = [{
        name: '当前站点',
        type: 'select',
        chars: siteNames,
        action: 'setCurrentUrl()',
        default: currentSiteName,
        style: {
            layout_flexBasisPercent: 1
        }
    },
    {
        name: '网站',
        type: 'button',
        action: 'toSite()',
        style: {
            layout_flexBasisPercent: 0.45
        }
    },
    {
        name: '公告',
        type: 'button',
        action: 'toNotice()',
        style: {
            layout_flexBasisPercent: 0.45
        }
    }
];

JSON.stringify(mainUI);

loginUrl:
function login() {}

function setCurrentUrl() {
    let currentSiteName = result.get("当前站点");
    const targetUrl = bookSites[currentSiteName];
    source.put("url", targetUrl);
}

function toSite() {
    const currentUrl = getCurrentUrl();
    java.startBrowser(currentUrl,"霹雳书屋");
}

function toNotice() {
  java.startBrowser("https://www.pilixiaoshuo.com/", "公告");
}

