@js:
const getUrl = (p) => baseUrl.replace(/\d+\/$/, `${p}/`);
let max = 200; // 取一个大数作为最后一页id
let lastUrl = getUrl(max);
const J = org.jsoup.Jsoup;
let doc = J.parse(result);
const list = [];
let listEl = doc.select(".listmh li a")
if(listEl.size()){
	 let lastDoc = J.parse(java.ajax(lastUrl))
	 let lastEl = lastDoc.select(".listmh li a").last()
	 if(lastEl){
	   max = String(lastEl.attr("href")).match(/-(\d+)\/$/)?.[1] || 1;
	   for(let i = 1; i <= max; i++){
	     let url = getUrl(i);
	     list.push({ title: `第${i}章`, url })
	   }
	 	}
}else{
	 list.push({title: "立即欣赏"})
}

list

