ruleContent.nextContentUrl:
#pb_next@class
@js:
var png=src.indexOf("next.png") > -1;
if(result&&png){
	var code=src.match(/eval\(function(.*)\)\);/)[0];
	//java.log(code)
	var regex=/\d+,'([+\w_]+)/;
	var next=code.match(regex)[1];
	//java.log(next)
	var url=String(next+".html");
	//java.log(url)
	result=url;
	}else{
		result="";
		}
result;

