    .build();
var response = client.newCall(request).execute();
if (!response.isSuccessful()) return '';
var raw = response.body().bytes();
if (raw.length < 32) return '';
var iv = Packages.java.util.Arrays.copyOfRange(raw, 0, 16);
var ct = Packages.java.util.Arrays.copyOfRange(raw, 16, raw.length);
var keyBytes = new Packages.java.lang.String('V4@.Tx+uXZn)AiH>').getBytes('UTF-8');
var keySpec = new Packages.javax.crypto.spec.SecretKeySpec(keyBytes, 'AES');
var ivSpec = new Packages.javax.crypto.spec.IvParameterSpec(iv);
var cipher = Packages.javax.crypto.Cipher.getInstance('AES/CBC/PKCS5Padding');
cipher.init(Packages.javax.crypto.Cipher.DECRYPT_MODE, keySpec, ivSpec);
var decrypted = cipher.doFinal(ct);
var base64 = Packages.java.util.Base64.getEncoder().encodeToString(decrypted);
return 'data:image/webp;base64,' + base64;
} catch(e) {
return '';
}
})();

